update public.content_variants set body = $json${"type":"multiple_choice","answer":"Purchasing power decreases","options":["Purchasing power increases","Purchasing power decreases","Purchasing power remains the same","Inflation has no effect"],"question":"What effect does inflation have on the purchasing power of money?","difficulty":"beginner","parameters":{},"explanation":"Inflation causes the price of goods to rise, so the same money can buy less."}$json$::jsonb where id = '416516f6-b2c2-4436-9ca9-a253a7d235d9';
update public.content_variants set body = $json${"type":"true_false","answer":false,"question":"If the price of goods rises, the purchasing power of the money we own also rises.","difficulty":"beginner","explanation":"When prices rise, the same money can buy fewer goods, so purchasing power decreases."}$json$::jsonb where id = '41c19172-9e63-4cfc-867a-34bd33e0eaaf';
