update public.content_variants set body = $json${"type":"multiple_choice","answer":"Rp. 900,000","options":["Rp. 900,000","IDR 1,100,000","Rp. 800,000","IDR 1,000,000"],"question":"Doni received a gross dividend of IDR 1,000,000 and 10% tax. What is the net dividend?","difficulty":"advanced","explanation":"10% tax on IDR 1,000,000 is IDR 100,000, so the net is IDR 900,000."}$json$::jsonb where id = '45e594d4-6e4b-4c70-b9b6-38535e8c05bc';
